create or replace function public.review_business_location_verification(p_location_id uuid,p_decision text,p_source_name text default null,p_source_url text default null) returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_loc public.business_locations%rowtype;v_actor uuid:=auth.uid();v_decision text:=lower(trim(coalesce(p_decision,'')));v_source_name text;v_source_url text;
begin if v_actor is null then raise exception 'authentication_required';end if;select * into v_loc from public.business_locations where id=p_location_id for update;if not found then raise exception 'location_not_found';end if;if not private.has_tenant_role(v_loc.tenant_id,array['admin','super_admin']::text[]) then raise exception 'insufficient_privilege';end if;if v_decision not in('verify','unverify') then raise exception 'invalid_decision';end if;if v_decision='verify' then if not v_loc.is_active then raise exception 'inactive_location_cannot_be_verified';end if;if nullif(trim(coalesce(v_loc.address_text,'')),'') is null then raise exception 'published_address_required';end if;v_source_name:=nullif(trim(coalesce(p_source_name,v_loc.source_name,'')),'');v_source_url:=nullif(trim(coalesce(p_source_url,v_loc.source_url,'')),'');if v_source_name is null or v_source_url is null then raise exception 'verification_source_required';end if;if v_source_url !~* '^https?://' then raise exception 'verification_source_url_invalid';end if;update public.business_locations set verified=true,source_name=v_source_name,source_url=v_source_url,source_checked_at=now(),updated_at=now() where id=p_location_id;insert into public.audit_logs(tenant_id,actor_user_id,action_type,action_text) values(v_loc.tenant_id,v_actor,'business_location_verified','Verified physical location '||p_location_id::text||' for business '||v_loc.business_id::text||' using documented source evidence.');else update public.business_locations set verified=false,source_checked_at=now(),updated_at=now() where id=p_location_id;insert into public.audit_logs(tenant_id,actor_user_id,action_type,action_text) values(v_loc.tenant_id,v_actor,'business_location_unverified','Removed verification from physical location '||p_location_id::text||' for business '||v_loc.business_id::text||'.');end if;return jsonb_build_object('ok',true,'location_id',p_location_id,'decision',v_decision,'verified',v_decision='verify');end;$$;
create or replace function public.review_business_verification(p_business_id uuid,p_decision text,p_source_name text default null,p_source_url text default null) returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_business public.businesses%rowtype;v_actor uuid:=auth.uid();v_decision text:=lower(trim(coalesce(p_decision,'')));v_source_name text;v_source_url text;
begin if v_actor is null then raise exception 'authentication_required';end if;select * into v_business from public.businesses where id=p_business_id for update;if not found then raise exception 'business_not_found';end if;if not private.has_tenant_role(v_business.tenant_id,array['admin','super_admin']::text[]) then raise exception 'insufficient_privilege';end if;if v_decision not in('verify','unverify') then raise exception 'invalid_decision';end if;if v_decision='verify' then if lower(coalesce(v_business.status,''))<>'published' then raise exception 'published_business_required';end if;v_source_name:=nullif(trim(coalesce(p_source_name,v_business.source_name,'')),'');v_source_url:=nullif(trim(coalesce(p_source_url,v_business.source_url,'')),'');if v_source_name is null or v_source_url is null then raise exception 'verification_source_required';end if;if v_source_url !~* '^https?://' then raise exception 'verification_source_url_invalid';end if;update public.businesses set verified=true,source_name=v_source_name,source_url=v_source_url,source_checked_at=now(),updated_at=now() where id=p_business_id;insert into public.audit_logs(tenant_id,actor_user_id,action_type,action_text) values(v_business.tenant_id,v_actor,'business_verified','Verified business '||p_business_id::text||' using documented source evidence.');else update public.businesses set verified=false,source_checked_at=now(),updated_at=now() where id=p_business_id;insert into public.audit_logs(tenant_id,actor_user_id,action_type,action_text) values(v_business.tenant_id,v_actor,'business_unverified','Removed verification from business '||p_business_id::text||'.');end if;return jsonb_build_object('ok',true,'business_id',p_business_id,'decision',v_decision,'verified',v_decision='verify');end;$$;
